add(14,'根據第1段內容，英珠有什麼可貴的品格？試指出兩項。答案須是兩字詞。',parts,
 parts.map(p=>official(p,['準確概括每項品格得2分，概念或表述欠準確得1分；不是兩字詞得0分。','可寫善良、真誠、純真等不同品格；近義答案只計較高分的一項，不能重複得分。'],['善良／真誠／誠實／純真／單純'],[example('善心',1,'概念接近善良，但詞語較像有善意之心，品格概括欠準確。'),example('誠懇／老實',1,'接近真誠，但概括欠準確。'),example('堅強／溫柔',1,'可由文意推敲，但未如善良、真誠或純真準確。'),example('勇敢／冷靜',0,'不是本題第1段可貴品格的準確概括。')],'2分：從照顧幼駒、羞澀表達和安撫旅伴，準確概括有據的品格；還須核對另一欄有否重複。')),
 lesson('trait',['trait','cause','meaning','technique'],'由英珠在具體處境中的言行，概括兩項不同而準確的品格。',[1],['把推銷時的神態、照顧幼駒的行動及安撫旅伴分開。它們各表現什麼內在特質？','所選兩字詞描述品格，還是一次行動或情緒？把兩項翻成白話後，是否其實只是同一種特質？'],['善良、真誠／誠實、純真／單純是可接受方向；善心、誠懇、老實、堅強、溫柔屬1分例答。','勇敢、冷靜不能因遇上雪暴便直接推出；要依她具體言行。','兩項須是兩字詞，且意思不同。真誠與誠實、純真與單純等同類答案只計一次，保留較高分。','未知的近義表達仍須對照準則自評；不能讓不同詞面掩蓋重複概念。'],['人物品格由處境中的言行歸納，選詞兼顧概念和格式。','要求兩項時，先比較兩詞的意思，確保不是改寫同一項。']),
 {distinctAnswerGroups:{keys:['i','ii'],groups:[['善良','善心'],['真誠','誠實','誠懇','老實'],['純真','單純']]},rubric:[{label:'品格',detail:'兩項都有第1段言行支持，不是只寫動作。'},{label:'兩字',detail:'每項是兩字詞。'},{label:'不同',detail:'兩項意涵不同，不重複計分。'}]});

p=choice('answer','對小說主角的感受或態度',2,['欣賞','體諒','批判','失望'],'B');
add(15,'根據第3段內容，作者對那個名字叫「英雄」的小說主角的感受或態度是怎樣的？',[p],[verifiedObjective(p)],
 lesson('meaning',['meaning','trait','cause','summary'],'問作者對人物的態度，要從敍述語氣和對其行為的解釋判斷。',[3],['把「沖昏頭腦」和「設身處地為他着想」放在一起，哪一部分最直接顯示作者如何看待他？','作者有沒有把悲劇簡單歸責於人物，還是說明他與時代環境的衝突？比較四項的態度強弱。'],['答案B：作者設身處地解釋欲望解放及境遇衝突，表現體諒。','作者年少時欣賞其溫度與理想，後來對其被成功沖昏頭腦曾感失望；但綜合人之常情及設身處地的解釋，整體態度是體諒。'],['感受態度題分清作者評價與人物命運。','以明確的評語、轉折和敍述視角判斷，不能從悲劇結果直接推負面態度。']),
 {optionAnalysis:options('answer',['早段確有對膽識的肯定，但下文更以設身處地解釋其弱點，整體較接近體諒。','作者沒有只責怪人物，反而從人性及時代境遇理解他的欲望與悲劇。','「設身處地為他着想」帶有理解與同情，不能只把「沖昏頭腦」讀成批判。','作者對人物被成功沖昏頭腦曾感失望，但這只是其中一層；結合人之常情、人性及設身處地，整體態度仍是體諒，不能只取局部失望。'])});

parts=[judgement('i','(i)凸顯龍蛇混雜的市集雜亂喧囂令人生厭。','否'),judgement('ii','(ii)說明不少有才華的人也流離於社會底層。','是')];
add(16,'根據第5段內容，判斷以下陳述是否作者描寫朝天宮環境的目的。',parts,parts.map(verifiedObjective),
 lesson('judgement',['judgement','effect','trait','summary'],'判斷環境描寫的用意，須以作者態度和它對藝人處境的作用核驗。',[5],['「有些凌亂」之後，作者緊接着如何評價這種凌亂？與「令人生厭」是否一致？','有真本領的藝人在哪裏工作、為什麼做批量耍貨？這個環境如何幫助理解他們的才華與生計？'],['(i)否、(ii)是。','作者說亂而有生氣，且兒時直奔馬師傅攤檔，不是強調厭惡喧囂。','馬師傅有真本領，卻在市集以耍貨謀生，環境凸顯有才華者仍處社會底層。'],['分析環境用意時，先確認作者態度，再連到人物處境。','描寫雜亂不等於表達厭惡；有才能也不代表在社會中地位高。']),
 {table:judgementTable(parts),optionAnalysis:[...judgementOptions('i','作者明說「也是因亂，所以帶有了生氣」，並以童年回憶肯定攤檔，與生厭不符。','這種環境有生命氣息，是人物謀生的背景，不是表達厭惡。','原段有明確評價及個人行為，已有判斷態度的依據。'),...judgementOptions('ii','馬師傅技藝精湛，卻為討生計在市集做耍貨，支持有才者仍處社會底層。','市集位置、生計和細貨／耍貨的對照，已有才華與社會處境之間的反差。','第5段詳細交代真本領及謀生方式，足以從環境推敲人物的社會處境。')]});

p=choice('answer','最恰當的結構劃分',2,['四部分：第1至2段、第3至4段、第5至8段、第9至10段','四部分：第1至3段、第4至6段、第7至8段、第9至10段','五部分：第1至2段、第3至4段、第5至6段、第7至9段、第10段','五部分：第1至3段、第4至5段、第6至7段、第8至9段、第10段'],'C');
add(20,'第二篇共有10段，以下哪一項結構的劃分最恰當？',[p],[verifiedObjective(p)],
 lesson('segmentation',['segmentation','structure','summary','title'],'依人物故事與綜合感想的轉換，判斷全文內容分組。',[1,3,5,7,10],['每個人物的故事之後，哪段仍在議論同一個人？把故事與緊接的感想配成組。','第7–9段的「這些人」「他們」指向一個人物，還是統攝前文三類人？末段又如何把個體連成整體？'],['答案C。第1–2段英珠及普通人的聲音，第3–4段小說主角及人之常情，第5–6段馬師傅及凋落。','第7–9段綜合前文人物與作者回望，末段以和音概括民間及時代輪廓。','人物轉換與由個案到綜合是分界；不能只按段數平均分組。'],['先分清故事、緊接的評論與全文綜合，把同一重點歸組。','分界須有敍述對象或論述層次的轉換，不能僅看段落長短。']),
 {optionAnalysis:options('answer',['第7、8段已由馬師傅轉到前文各人物的綜合回望，與第5、6段的個案應分開。','第3段已轉入小說主角，不宜與英珠同組；第5段也轉入馬師傅，不能接在同一部分。','三個故事各連其感想，再由第7–9段綜合，末段用和音總結民間，分界有內容依據。','把小說主角的第3段留在英珠部分，又拆開馬師傅故事與凋落感想，不能保留各組的中心。'])});

samples['dse2026-q9']={ii:[
 {id:'dse2026-q9-ii-s1',score:4,text:'人工智能缺乏對於價值觀的取捨標準和概念。例如一個警察還是三個罪犯的困境，人工智能只有不傷害的設定難以作取捨。警察屬正義的一方，而罪犯屬不義的一方，看似警察比罪犯優先；但警察得一人而罪犯有三人，人數上又似乎是罪犯比警察優先。這時便出現取捨矛盾。人工智能沒有評判與作出回應的能力，正因價值觀是因人而異的，但人工智能只存在恆定、數據化的標準，因此人工智能不可能取代99%人類的智力勞動。',analysis:'4分：論點準確，分開正義與人數兩種取向，具體說明它們如何互相牽制，再連到固定標準無法統一取捨，闡述飽滿。'},
 {id:'dse2026-q9-ii-s2',score:3,text:'作者想借此說明在面對涉及價值觀的問題之事，人工智能無法抉擇，所以技術萬能的烏托邦難以實現。以車禍事故為例，是保護精忠為國為民的警察，還是品行惡劣的三個罪犯，因好壞而保護警察，罪犯的生命就不是生命了嗎；相反，保護以三條性命為人數的罪犯，好警察的性命不應更重要。就算如何抉擇，都會有爭議的發生，因而矛盾。作者藉此帶出每個人的價值觀因人而異，終有爭議矛盾。',analysis:'3分：理解價值觀差異準確，亦合理對照品行與性命數量；但較偏以問句輪流質疑，未如4分例答把兩方取向及固定程式的限制說得飽滿。'},
 {id:'dse2026-q9-ii-s4',score:2,text:'作者藉引文說明機器人一直都未能有價值觀，有道德上的取捨，權衡其得失，進行哲學等的思考，就如事故難以避免時，優先的是一個警察還是三個罪犯，警察是善良的，而罪犯是帶罪之人，但優先正義的警察卻會害死更多生命，而優先犯罪的惡人只會失去一條人命，令人難以捨棄，但機器未能像人一樣，即使困難也能得出答案。',analysis:'2分：例子已說到正義與人命數量的衝突，但論點仍主要是機器沒有價值觀、做不到；欠「因人而異」的準確概括，闡述一般。'},
 {id:'dse2026-q9-ii-s6',score:1,text:'說明現今科技看似萬能、進步飛速，但事實上卻是充滿難點，一旦涉及價值觀的課題人工智能便陷入困境。例如自動駕駛一旦事故發生時系統是優先保護車外人，還是車內人？是優先一個警察還是三個罪犯？這一些涉及價值觀和道德倫理便是一大困境，這也充分說明科技雖看似萬能，實際上人工智能無法分辨價值和權衡的難度。',analysis:'1分：有觸及價值觀與技術限制，但只是列出困境，未分析兩方各代表什麼價值，也沒有說清因人而異如何造成矛盾。'},
 {id:'dse2026-q9-ii-s8',score:0,text:'是優先一個猛漢還是一個盲童，一個困境中有優勢，另外一個困境中沒有優勢。我會選擇盲童，因為盲童身上有缺陷，我認為盲童更加需要幫助，而猛漢看似是不需要幫助，所以人們常常會幫助一些有需要的人。',analysis:'0分：只表達自己選擇盲童的喜好，未回應價值觀差異或矛盾及機器的限制，核心論點錯誤。'}
]};
const objectivePages={9:43,10:50,11:52,12:54,15:57,16:58,20:79};
for(const q of questions)for(const p of q.answerParts.filter(p=>p.kind==='choice')){q.official.find(o=>o.key===p.key).criteria=['教師會議簡報第'+objectivePages[q.number]+'頁已以星號核實答案，答對'+p.marks+'分。'];}
